/* Real tabs retain the original forms, event handlers and task permissions. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),previous=detail;
detail=async function(id,...args){await previous(id,...args);const dialog=document.querySelector(shared?'#sharedDialog':'#details'),root=document.querySelector(shared?'#sharedDetail':'#detailBody');if(!dialog?.open||!root||!tasks.some(t=>t.id===id))return;const head=root.querySelector('.shared-task-head,.dialog-head');if(!head)return;document.body.classList.remove('task-drawer-open');dialog.classList.add('task-focus-layout');const sections=[...root.querySelectorAll('.shared-section,.task-section')],conversation=sections.find(s=>/گزارش و بازخورد|گفت‌وگو و بازخورد/.test(s.querySelector('h3')?.textContent||'')),files=sections.find(s=>/فایل/.test(s.querySelector('h3')?.textContent||'')),history=[...root.querySelectorAll('details')].find(d=>/همه سوابق|سوابق ارسال و تأیید/.test(d.querySelector('summary')?.textContent||'')),facts=root.querySelector('.shared-facts,.task-facts'),actions=root.querySelector('.shared-actions,.detail-actions'),overview=document.createElement('section'),nav=document.createElement('div');nav.className='task-focus-nav';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','بخش‌های کار');[...root.childNodes].forEach(n=>{if(n!==head&&n!==facts&&n!==actions)overview.append(n)});head.after(...[facts,actions,nav].filter(Boolean));const panels=[];if(conversation||history){const p=document.createElement('section');if(conversation)p.append(conversation);if(history){history.open=false;p.append(history)}panels.push(['گفت‌وگو و سوابق',p])}if(files){const p=document.createElement('section');p.append(files);panels.push(['فایل‌ها و نسخه‌ها',p])}panels.push(['مشخصات و ارجاع',overview]);const buttons=[];function select(index,focus=false){panels.forEach(([,p],i)=>{p.hidden=i!==index;buttons[i].setAttribute('aria-selected',String(i===index));buttons[i].tabIndex=i===index?0:-1});if(focus)buttons[index].focus();dialog.scrollTop=0}panels.forEach(([title,p],i)=>{p.className='task-focus-panel';p.id='task-panel-'+i;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby','task-tab-'+i);const b=document.createElement('button');b.type='button';b.id='task-tab-'+i;b.textContent=title;b.setAttribute('role','tab');b.setAttribute('aria-controls',p.id);b.onclick=()=>select(i);b.onkeydown=e=>{let n=i;if(e.key==='ArrowLeft')n=(i+1)%panels.length;else if(e.key==='ArrowRight')n=(i-1+panels.length)%panels.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=panels.length-1;else return;e.preventDefault();select(n,true)};buttons.push(b);nav.append(b);root.append(p)});const upload=overview.querySelector('#desktopUploadShortcut');if(upload)upload.hidden=true;const edit=root.querySelector('#editCollaborators');if(edit)edit.onclick=()=>{select(panels.length-1);const assignment=root.querySelector('#taskAssignment');if(assignment)assignment.open=true};select(args[0]===true&&files?panels.findIndex(([,p])=>p.contains(files)):0);dialog.addEventListener('close',()=>dialog.classList.remove('task-focus-layout'),{once:true})};})();